struct Test{vector<int>cmd,pos;};
struct Allocator{
 bool emit=true; int T=0;map<int,int>g;set<pair<int,int>>sizes;vector<pair<int,int>>pipes{{0,0}};
 void erase(map<int,int>::iterator it){sizes.erase({it->second-it->first,it->first});g.erase(it);}
 void add(int l,int r){if(l>=r)return;auto it=g.lower_bound(l);if(it!=g.begin()){auto p=prev(it);if(p->second==l){l=p->first;erase(p);}}it=g.lower_bound(l);if(it!=g.end()&&it->first==r){r=it->second;erase(it);}g[l]=r;sizes.insert({r-l,l});}
 bool fits(int x,int n){if(x<0||x+n>100000000)return false;if(x>=T)return true;auto it=g.upper_bound(x);if(it==g.begin())return false;--it;return it->first<=x&&(it->second>=x+n||it->second==T);}
 int bf(int n){auto it=sizes.lower_bound({n,-1});if(it!=sizes.end())return it->second;if(!g.empty()&&prev(g.end())->second==T)return prev(g.end())->first;return T;}
 void place(int n,int x){int digs=max(0,(x+n-T+19)/20);if(digs){add(T,T+20*digs);T+=20*digs;}auto it=g.upper_bound(x);if(it==g.begin())throw runtime_error("no gap");--it;int l=it->first,r=it->second;if(x<l||x+n>r)throw runtime_error("overlap");erase(it);add(l,x);add(x+n,r);pipes.push_back({x,n});if(emit)printf("%d %d\n",digs,x);}
 void remove(int id){if(id<=0||id>=(int)pipes.size()||pipes[id].second<=0)throw runtime_error("bad PID");auto p=pipes[id];add(p.first,p.first+p.second);pipes[id].second=0;if(emit)printf("%d\n",p.first);}
};


// Import only observed commands and their immutable physical positions.
void importObserved(fallback_online::Allocator& out,const Allocator& actual,
                    const vector<int>& observed){
 int next=0;
 for(int command:observed){
  out.lifetimeModel.advance();
  if(command>0){
   const int id=++next;
   if(out.observedRunLength!=command){
    if(out.observedRunCount){
     out.completedPlacementRuns.emplace_back(out.observedRunLength,out.observedRunCount);
     if(out.completedPlacementRuns.size()>8)out.completedPlacementRuns.pop_front();
    }
    out.observedRunLength=command;out.observedRunCount=0;
    out.activeRunFirstPid=id;out.activeRunDeleteParityCount={};
   }
   ++out.observedRunCount;
   const int cohort=out.lengthOccurrenceCount[command]%2;
   const auto x=actual.pipes[id].first;
   out.pipes.push_back(fallback_online::Pipe{x,command,true,cohort});
   out.activeByEnd.emplace(x+command,id);out.fenwickAdd(id,1);++out.activePipeCount;
   ++out.lengthOccurrenceCount[command];out.recordLength(command);
   out.recordObservation(fallback_online::Observation{1,command});out.recordPrimalEvent(command);
  }else{
   const int id=-command;auto& p=out.pipes[id];
   const int rank=out.rankFromNewestPermille(id);
   out.lifetimeModel.observeDeletion(id);out.activeByEnd.erase(p.start+p.length);
   p.active=false;out.fenwickAdd(id,-1);--out.activePipeCount;
   out.recordDeletionPattern(id,p.length);out.recordPrimalEvent(-1);
   out.recordObservation(fallback_online::Observation{-1,rank});
   ++out.removedLengthCohort[p.length][p.sizeCohort];
   if(id>=out.activeRunFirstPid)++out.activeRunDeleteParityCount[id&1];
  }
 }
 out.trenchLength=actual.T;
 for(auto [left,right]:actual.g)out.addFreeGap(left,right,-1,++out.releaseEpoch);
 // A slab reservation made by a different placement policy cannot be imported.
 out.cohortSlabActive=false;
 if(out.activePipeCount>fallback_online::kMcMaxActivePipes)out.lifoLaneDisabledForScale=true;
 if(out.pipes.size()!=actual.pipes.size())throw runtime_error("import PID count");
 for(size_t id=1;id<actual.pipes.size();++id){
  const auto& p=out.pipes[id];
  if(p.start!=actual.pipes[id].first||p.active!=(actual.pipes[id].second>0))throw runtime_error("import geometry");
 }
 if(out.fenwickPrefix(int(out.pipes.size()-1))!=int(out.activePipeCount))throw runtime_error("import rank index");
}



void adoptOnline(Allocator& actual,const fallback_online::Allocator& from){
 actual.T=int(from.trenchLength);actual.g.clear();actual.sizes.clear();
 actual.pipes.clear();actual.pipes.push_back({0,0});
 vector<pair<int,int>> live;live.reserve(from.activePipeCount);
 for(size_t id=1;id<from.pipes.size();++id){
  auto p=from.pipes[id];actual.pipes.push_back({int(p.start),p.active?p.length:0});
  if(p.active)live.push_back({int(p.start),int(p.start)+p.length});
 }
 sort(live.begin(),live.end());int cursor=0;
 for(auto [left,right]:live){
  if(left<cursor||right>actual.T)throw runtime_error("invalid occupied snapshot");
  actual.add(cursor,left);cursor=right;
 }
 actual.add(cursor,actual.T);
}

// Causal, paired counterfactual search. No public-test suffix is used here.
// Persistent interval trees share unchanged gaps between simulated trajectories.
#include <ctime>
#include <climits>
#include <numeric>

// Process CPU = user + kernel/system; excludes time waiting for the interactor.
// The solver has one worker thread. Do not divide this value by core count.
#include <cstdint>
#include <limits>
#if defined(_WIN32)
#ifndef NOMINMAX
#define NOMINMAX
#endif
#ifndef WIN32_LEAN_AND_MEAN
#define WIN32_LEAN_AND_MEAN
#endif
#include <windows.h>
#else
#include <sys/resource.h>
#endif

namespace pipes_cpu {
inline double seconds() noexcept {
#if defined(_WIN32)
    FILETIME created{},exited{},kernel{},user{};
    if(!GetProcessTimes(GetCurrentProcess(),&created,&exited,&kernel,&user))
        return std::numeric_limits<double>::infinity();
    const auto ticks=[](const FILETIME& t){return (std::uint64_t(t.dwHighDateTime)<<32)|std::uint64_t(t.dwLowDateTime);};
    return (double(ticks(kernel))+double(ticks(user)))*1e-7;
#else
    rusage usage{};
    if(getrusage(RUSAGE_SELF,&usage)!=0)return std::numeric_limits<double>::infinity();
    return double(usage.ru_utime.tv_sec)+double(usage.ru_stime.tv_sec)
        +(double(usage.ru_utime.tv_usec)+double(usage.ru_stime.tv_usec))*1e-6;
#endif
}
}

// Conservative provisional profile. These are not measurements on the G5420.
#ifndef PIPES_MEMO_BUCKET_LOG2
#define PIPES_MEMO_BUCKET_LOG2 19
#endif
static_assert(PIPES_MEMO_BUCKET_LOG2>=16&&PIPES_MEMO_BUCKET_LOG2<=21);
constexpr double kHardwarePlannerCpu=2.5;
constexpr double kHardwareSearchStopCpu=3.8;
constexpr double kHardwareProcessEnvelope=4.0;
constexpr double kHardwareReserveSafety=1.25;

namespace robust_search {
using U = uint32_t;
struct Exhausted {};
struct Node { U left=0,right=0,priority=0; int start=0,end=0,maxGap=0; };
static_assert(sizeof(Node)==24);

struct Arena {
    // 80 MiB node arena, configurable memo (32 MiB default), and delayed probes.
    // public replay pays neither cost. Leave RSS margin for live state/tables.
    static constexpr size_t cap=80u*1024u*1024u/sizeof(Node);
    vector<Node> a;
    size_t highWater=0;
    Arena(){a.reserve(cap);a.push_back({});}
    void reset(){highWater=max(highWater,a.size());a.resize(1);}
    U put(Node n){if(a.size()>=cap)throw Exhausted{};a.push_back(n);return U(a.size()-1);}
    U copy(U p){return put(a[p]);}
    static U hash(U x){x^=x>>16;x*=0x7feb352dU;x^=x>>15;x*=0x846ca68bU;return x^(x>>16);}
    U leaf(int l,int r,bool bySize){return put({0,0,hash(U(l)^U(r-l)*0x9e3779b9U^(bySize?0x85ebca6bU:0)),l,r,r-l});}
    void pull(U p){a[p].maxGap=max({a[p].end-a[p].start,a[a[p].left].maxGap,a[a[p].right].maxGap});}
    // Explicit key comparisons avoid temporary tree allocations in searches.
    static bool keyLess(int l,int r,int x,int y,bool sz){return sz?pair(r-l,l)<pair(y-x,x):l<x;}
    pair<U,U> divide(U p,int l,int r,bool sz){
        if(!p)return {0,0};
        U q=copy(p);
        if(keyLess(a[p].start,a[p].end,l,r,sz)){
            auto [x,y]=divide(a[p].right,l,r,sz);a[q].right=x;pull(q);return {q,y};
        }
        auto [x,y]=divide(a[p].left,l,r,sz);a[q].left=y;pull(q);return {x,q};
    }
    U merge(U x,U y){
        if(!x||!y)return x?x:y;
        if(a[x].priority<a[y].priority){U q=copy(x);U z=merge(a[x].right,y);a[q].right=z;pull(q);return q;}
        U q=copy(y);U z=merge(x,a[y].left);a[q].left=z;pull(q);return q;
    }
    U insert(U p,U n,bool sz){
        if(!p)return n;
        if(a[n].priority<a[p].priority){
            auto [x,y]=divide(p,a[n].start,a[n].end,sz);a[n].left=x;a[n].right=y;pull(n);return n;
        }
        U q=copy(p);
        if(keyLess(a[n].start,a[n].end,a[p].start,a[p].end,sz)){
            U z=insert(a[p].left,n,sz);a[q].left=z;
        }else{U z=insert(a[p].right,n,sz);a[q].right=z;}
        pull(q);return q;
    }
    U erase(U p,int l,int r,bool sz){
        if(!p)throw runtime_error("counterfactual gap missing");
        if(a[p].start==l&&a[p].end==r)return merge(a[p].left,a[p].right);
        U q=copy(p);
        if(keyLess(l,r,a[p].start,a[p].end,sz)){U z=erase(a[p].left,l,r,sz);a[q].left=z;}
        else{U z=erase(a[p].right,l,r,sz);a[q].right=z;}
        pull(q);return q;
    }
    U before(U p,int x)const{U found=0;while(p){if(a[p].start<=x){found=p;p=a[p].right;}else p=a[p].left;}return found;}
    U after(U p,int x)const{U found=0;while(p){if(a[p].start>=x){found=p;p=a[p].left;}else p=a[p].right;}return found;}
    U best(U p,int n)const{U found=0;while(p){if(a[p].end-a[p].start>=n){found=p;p=a[p].left;}else p=a[p].right;}return found;}
    U first(U p,int n)const{
        if(!p||a[p].maxGap<n)return 0;
        while(p){if(a[a[p].left].maxGap>=n)p=a[p].left;else if(a[p].end-a[p].start>=n)return p;else p=a[p].right;}return 0;
    }
};

struct Layout {
    Arena* arena; U startRoot=0,sizeRoot=0; int T=0;
    void rawAdd(int l,int r){if(l>=r)return;U n=arena->leaf(l,r,false);startRoot=arena->insert(startRoot,n,false);n=arena->leaf(l,r,true);sizeRoot=arena->insert(sizeRoot,n,true);}
    void eraseGap(int l,int r){startRoot=arena->erase(startRoot,l,r,false);sizeRoot=arena->erase(sizeRoot,l,r,true);}
    void release(int l,int r){
        U p=arena->before(startRoot,l);
        if(p&&arena->a[p].end==l){int x=arena->a[p].start;eraseGap(x,l);l=x;}
        p=arena->after(startRoot,l);
        if(p&&arena->a[p].start==r){int y=arena->a[p].end;eraseGap(r,y);r=y;}
        rawAdd(l,r);
    }
    int bf(int n,int policy=0)const{
        U p=policy==1?arena->first(startRoot,n):arena->best(sizeRoot,n);
        if(p)return arena->a[p].start;
        p=arena->before(startRoot,T);
        return p&&arena->a[p].end==T?arena->a[p].start:T;
    }
    void place(int n,int x){
        if(x+n>T){int old=T;T=20*((x+n+19)/20);release(old,T);}
        U p=arena->before(startRoot,x);
        if(!p||arena->a[p].end<x+n)throw runtime_error("counterfactual overlap");
        int l=arena->a[p].start,r=arena->a[p].end;eraseGap(l,r);rawAdd(l,x);rawAdd(x+n,r);
    }
};

struct Event {int length=0,rank=0,exact=0;};
uint64_t mix64(uint64_t x){x^=x>>30;x*=0xbf58476d1ce4e5b9ULL;x^=x>>27;x*=0x94d049bb133111ebULL;return x^(x>>31);}
uint64_t pipeHash(int pid,int x,int n,uint64_t salt){return mix64(uint64_t(pid)*0x9e3779b97f4a7c15ULL^uint64_t(x)*0x632be59bd9b4e019ULL^uint64_t(n)*salt);}
struct MemoEntry {uint64_t a=0,b=0;int trench=0;uint32_t occupied=0;};
static_assert(sizeof(MemoEntry)==24);
struct alignas(64) MemoBucket {MemoEntry slots[2];};
static_assert(sizeof(MemoBucket)==64);
struct Memo {
    // Two entries per cache line; compare 32/128 MiB on the actual target.
    static constexpr size_t count=1u<<PIPES_MEMO_BUCKET_LOG2;
    vector<MemoBucket> table{count};
    uint64_t hits=0,queries=0,stores=0;uint32_t tick=0;
    int get(uint64_t a,uint64_t b){++queries;for(auto& e:table[a&(count-1)].slots)if(e.occupied&&e.a==a&&e.b==b){++hits;e.occupied=++tick;return e.trench;}return -1;}
    void put(uint64_t a,uint64_t b,int T){auto& bucket=table[a&(count-1)];int slot=0;
        if(bucket.slots[1].a==a&&bucket.slots[1].b==b)slot=1;
        else if(!(bucket.slots[0].a==a&&bucket.slots[0].b==b)&&bucket.slots[1].occupied<bucket.slots[0].occupied)slot=1;
        bucket.slots[slot]={a,b,T,++tick};++stores;
    }
};
struct Scenario {vector<int> commands;int policy=0;array<uint64_t,129> suffixA{},suffixB{};};
struct Fenwick {
    vector<int> b;
    explicit Fenwick(int n):b(n+1){}
    void add(int x,int d){for(;x<int(b.size());x+=x&-x)b[x]+=d;}
    int sum(int x)const{int r=0;for(;x;x-=x&-x)r+=b[x];return r;}
    int kth(int k)const{int p=0;for(int d=1<<18;d;d>>=1)if(p+d<int(b.size())&&b[p+d]<k){k-=b[p+d];p+=d;}return p+1;}
};

static weak_ptr<Arena> sharedArena;static weak_ptr<Memo> sharedMemo;static double sharedSearchCpu=0;
class Planner {
    struct Probe {unique_ptr<Allocator> state;size_t step;int length,baseline,proposed;};
    vector<Event> history;
    vector<int> observedCommands;
    deque<Probe> pending;
    Fenwick actualRanks{200002};
    vector<int> activeIds;
    int live=0,nextPid=0,placements=0;
    double usedCpu=0;
    double startCpu=pipes_cpu::seconds();
    shared_ptr<Arena> arena;
    shared_ptr<Memo> memo;
    uint64_t physicalA=0,physicalB=0;
    uint64_t savedQueries=0,savedHits=0,savedStores=0;unsigned releases=0;bool scratchDisabled=false;
    int confidence=0;
    void releaseScratch(){
        pending.clear();
        if(memo){savedQueries+=memo->queries;savedHits+=memo->hits;savedStores+=memo->stores;memo.reset();++releases;}
        if(arena){peakNodes=max(peakNodes,arena->a.size());arena.reset();}
    }
    void stopForScale(){if(memo||arena)scratchDisabled=true;releaseScratch();}
    uint32_t rng=0x31415927;
    void charge(double dt){usedCpu+=dt;sharedSearchCpu+=dt;}
    static double cpu(){return pipes_cpu::seconds();}
    double headroom(double currentSearch=0)const{
        // N is not revealed. Reserve for the maximum legal remaining stream,
        // including interactive I/O and map maintenance. A fixed search budget
        // alone is unsafe: ordinary processing can exceed two CPU seconds.
        double now=cpu(),seen=max<size_t>(1,history.size());
        double ordinary=max(0.0,now-startCpu-sharedSearchCpu-currentSearch);
        double rate=max(0.000016,ordinary/seen);
        double reserve=max(0.0,200000.0-seen)*rate;
        return kHardwareProcessEnvelope-now-reserve*kHardwareReserveSafety;
    }
    uint32_t random(){rng^=rng<<13;rng^=rng>>17;rng^=rng<<5;return rng;}
    vector<Scenario> scenarios(const Allocator& actual,int request){
        constexpr int count=64,depth=128;
        vector<Scenario> out;out.reserve(count);
        int N=int(history.size()),window=min(N,8192);
        vector<int> starts;
        for(int context=4;context>=1&&starts.size()<8;--context){
            starts.clear();
            for(int s=max(context,N-window);s+depth<N;++s){
                bool same=true;
                for(int k=0;k<context&&same;++k){
                    auto a=history[N-context+k],b=history[s-context+k];
                    same=a.length==b.length&&(a.length>0||abs(a.rank-b.rank)<128);
                }
                if(same)starts.push_back(s);
            }
        }
        activeIds.clear();activeIds.reserve(live+depth+1);
        for(int id=1;id<int(actual.pipes.size());++id)if(actual.pipes[id].second)activeIds.push_back(id);
        const int base=int(actual.pipes.size());activeIds.push_back(base);
        array<int,41> freq{};
        for(int i=max(0,N-512);i<N;++i)if(history[i].length>0)++freq[history[i].length];
        int common=int(max_element(freq.begin()+1,freq.end())-freq.begin());
        for(int trial=0;trial<count;++trial){
            Scenario sc;sc.policy=trial%8==7?1:0;sc.commands.reserve(depth);
            Fenwick ranks(base+depth+3);for(int id:activeIds)ranks.add(id,1);
            int alive=int(activeIds.size()),pid=base;
            int begin=starts.empty()?max(0,N-window)+int(random()%max(1,window-depth)):starts[random()%starts.size()];
            for(int k=0;k<depth;++k){
                Event ev=history[min(begin+k,N-1)];
                // Contiguous blocks retain observed deletion/size correlation.
                // Eight distribution-shift probes add no-deletion size bursts.
                if(trial>=40&&trial<48){ev.length=trial<44?(trial%2?40:common):(trial%2?request:1);}
                if(ev.length>0){sc.commands.push_back(ev.length);ranks.add(++pid,1);++alive;}
                else if(alive){
                    int rank=ev.exact>=0?min(alive-1,ev.exact):int(int64_t(ev.rank)*(alive-1)/1000);
                    if(trial>=48){if(trial%4==0)rank=0;else if(trial%4==1)rank=alive-1;else if(trial%4==2)rank=alive-1-rank;else rank=int(random()%alive);}
                    int id=ranks.kth(alive-rank);ranks.add(id,-1);--alive;sc.commands.push_back(-id);
                }
            }
            sc.suffixA[depth]=0x517cc1b727220a95ULL;sc.suffixB[depth]=0x6eed0e9da4d94a4fULL;
            // Every generated scenario currently has exactly depth commands.
            // The guard also supports a shorter all-empty history safely.
            size_t size=sc.commands.size();sc.suffixA[size]=0x517cc1b727220a95ULL;sc.suffixB[size]=0x6eed0e9da4d94a4fULL;
            for(size_t k=size;k-->0;){sc.suffixA[k]=mix64(uint64_t(int64_t(sc.commands[k]))+0x9e3779b97f4a7c15ULL*sc.suffixA[k+1]);sc.suffixB[k]=mix64(uint64_t(int64_t(sc.commands[k]))+0x632be59bd9b4e019ULL*sc.suffixB[k+1]);}
            out.push_back(std::move(sc));
        }
        return out;
    }
    vector<int> actions(const Allocator& s,int n,int baseline){
        vector<int> a{baseline};int digs=max(0,(baseline+n-s.T+19)/20);
        auto add=[&](int x){if(x>=0&&max(0,(x+n-s.T+19)/20)<=digs&&find(a.begin(),a.end(),x)==a.end())a.push_back(x);};
        int count=0;
        for(auto it=s.sizes.lower_bound({n,-1});it!=s.sizes.end()&&count<5;++it,++count){int l=it->second,r=l+it->first;add(l);add(r-n);}
        for(auto [l,r]:s.g)if(r-l>=n){add(l);add(r-n);break;}
        for(auto it=s.g.rbegin();it!=s.g.rend();++it)if(it->second-it->first>=n){add(it->first);add(it->second-n);break;}
        if(!s.g.empty()&&s.g.rbegin()->second==s.T)add(s.g.rbegin()->first);
        if(a.size()>16)a.resize(16);
        return a;
    }
    int simulate(Layout s,int x,int n,const Scenario& sc,const Allocator& actual){
        s.place(n,x);int base=int(actual.pipes.size());
        array<pair<int,int>,130> predicted{};predicted[0]={x,n};int count=1;
        uint64_t a=physicalA^pipeHash(base,x,n,0x94d049bb133111ebULL);
        uint64_t b=physicalB^pipeHash(base,x,n,0xbf58476d1ce4e5b9ULL);
        array<pair<uint64_t,uint64_t>,17> visited{};int visits=0,answer=-1;
#if defined(ROBUST_VERIFY_MEMO)
        int expected=-1;
#endif
        for(size_t k=0;k<sc.commands.size();++k){
            if(k%8==0){
                uint64_t ka=mix64(a^uint64_t(s.T)*0xd6e8feb86659fd93ULL^uint64_t(base+count)*0x517cc1b727220a95ULL^uint64_t(sc.policy))^sc.suffixA[k];
                uint64_t kb=mix64(b^uint64_t(s.T)*0xa0761d6478bd642fULL^uint64_t(base+count)*0x6eed0e9da4d94a4fULL^uint64_t(sc.policy))^sc.suffixB[k];
                int hit=memo->get(ka,kb);
                if(hit>=0){
#if defined(ROBUST_VERIFY_MEMO)
                    if(expected>=0&&hit!=expected)throw runtime_error("memo inconsistent suffix");expected=hit;
#else
                    answer=hit;break;
#endif
                }
                visited[visits++]={ka,kb};
            }
            int c=sc.commands[k];
            if(c>0){int pos=s.bf(c,sc.policy);s.place(c,pos);int id=base+count;predicted[count++]={pos,c};a^=pipeHash(id,pos,c,0x94d049bb133111ebULL);b^=pipeHash(id,pos,c,0xbf58476d1ce4e5b9ULL);}
            else{int id=-c;auto p=id<base?actual.pipes[id]:predicted[id-base];s.release(p.first,p.first+p.second);a^=pipeHash(id,p.first,p.second,0x94d049bb133111ebULL);b^=pipeHash(id,p.first,p.second,0xbf58476d1ce4e5b9ULL);}
            ++simulatedEvents;
        }
        if(answer<0)answer=s.T;
#if defined(ROBUST_VERIFY_MEMO)
        if(expected>=0&&answer!=expected)throw runtime_error("memo terminal mismatch");
#endif
        for(int i=0;i<visits;++i)memo->put(visited[i].first,visited[i].second,answer);
        return answer;
    }
    void checkDelayed(){
        if(pending.empty()||pending.front().step+129>observedCommands.size())return;
        if(!arena||!memo){pending.clear();return;}
        if(pending.front().step+512<observedCommands.size()){pending.pop_front();confidence=0;return;}
        if(headroom()<0.02)return;
        auto probe=std::move(pending.front());pending.pop_front();double begin=cpu();
        try{
            Scenario sc;sc.commands.assign(observedCommands.begin()+probe.step+1,observedCommands.begin()+probe.step+129);
            sc.suffixA[128]=0x517cc1b727220a95ULL;sc.suffixB[128]=0x6eed0e9da4d94a4fULL;
            for(int k=127;k>=0;--k){sc.suffixA[k]=mix64(uint64_t(int64_t(sc.commands[k]))+0x9e3779b97f4a7c15ULL*sc.suffixA[k+1]);sc.suffixB[k]=mix64(uint64_t(int64_t(sc.commands[k]))+0x632be59bd9b4e019ULL*sc.suffixB[k+1]);}
            const auto& state=*probe.state;physicalA=physicalB=0;
            for(size_t id=1;id<state.pipes.size();++id)if(state.pipes[id].second){auto [x,n]=state.pipes[id];physicalA^=pipeHash(int(id),x,n,0x94d049bb133111ebULL);physicalB^=pipeHash(int(id),x,n,0xbf58476d1ce4e5b9ULL);}
            arena->reset();Layout initial{arena.get(),0,0,state.T};for(auto [l,r]:state.g)initial.rawAdd(l,r);
            int ordinary=simulate(initial,probe.baseline,probe.length,sc,state);
            int alternative=simulate(initial,probe.proposed,probe.length,sc,state);
            if(alternative<ordinary){++verifiedWins;confidence=min(8,confidence+2);}
            else if(alternative==ordinary){++verifiedTies;confidence=min(8,confidence+1);}
            else{++verifiedLosses;confidence=max(0,confidence-4);}
            peakNodes=max(peakNodes,arena->a.size());arena->reset();
        }catch(const Exhausted&){confidence=0;++aborted;arena->reset();}
        charge(cpu()-begin);
        if(usedCpu>kHardwarePlannerCpu||cpu()>kHardwareSearchStopCpu)releaseScratch();
    }
public:
    unsigned decisions=0,changes=0,aborted=0;uint64_t simulatedEvents=0,logicalEvents=0;size_t peakNodes=0;
    unsigned proposalsMade=0,verifiedWins=0,verifiedTies=0,verifiedLosses=0;
    void observe(int command,size_t gapCount=0){
        observedCommands.push_back(command);
        if(command>0){actualRanks.add(++nextPid,1);++live;++placements;history.push_back({command,0,0});}
        else{
            int rank=live-actualRanks.sum(-command);
            int exact=rank<=16?rank:-1;
            history.push_back({0,live>1?int(int64_t(rank)*1000/(live-1)):0,exact});
            actualRanks.add(-command,-1);--live;
        }
        // Do not retain a large search workspace while the physical allocator
        // grows beyond the size on which this planner is allowed to operate.
        if(live>8192||gapCount>4096)stopForScale();
        checkDelayed();
    }
    int choose(const Allocator& actual,int n,int baseline){
#if defined(ROBUST_TEST_DECISIONS)
        if(decisions>=ROBUST_TEST_DECISIONS)return baseline;
#endif
        // Bounded search is reserved for genuinely different placements. Work
        // is periodically sampled, rather than exhausting the budget at start.
        if(history.size()<256)return baseline;
        if(scratchDisabled)return baseline;
        if(live>8192||actual.g.size()>4096){stopForScale();return baseline;}
        if(logicalEvents>=12000000||usedCpu>kHardwarePlannerCpu||cpu()>kHardwareSearchStopCpu){releaseScratch();return baseline;}
        if(placements%16!=0)return baseline;
        // Avoid repeatedly starting batches as small time credits arrive.
        if(headroom()<0.04)return baseline;
        double begin=cpu();auto candidates=actions(actual,n,baseline);
        if(candidates.size()<2){charge(cpu()-begin);return baseline;}
        int answer=baseline;
        try{
            auto futures=scenarios(actual,n);
            if(!arena){arena=sharedArena.lock();if(!arena){arena=make_shared<Arena>();sharedArena=arena;}}arena->reset();
            if(!memo){memo=sharedMemo.lock();if(!memo){memo=make_shared<Memo>();sharedMemo=memo;}}
            physicalA=physicalB=0;
            for(int id:activeIds)if(id<int(actual.pipes.size())){auto [x,L]=actual.pipes[id];physicalA^=pipeHash(id,x,L,0x94d049bb133111ebULL);physicalB^=pipeHash(id,x,L,0xbf58476d1ce4e5b9ULL);}
            Layout initial{arena.get(),0,0,actual.T};for(auto [l,r]:actual.g)initial.rawAdd(l,r);
            vector<vector<int>> outcome(candidates.size());bool complete=true;
            for(size_t a=0;a<candidates.size()&&complete;++a){
                for(const auto& sc:futures){
                    outcome[a].push_back(simulate(initial,candidates[a],n,sc,actual));++simulatedEvents;logicalEvents+=sc.commands.size()+1;
                    if((usedCpu+cpu()-begin>kHardwarePlannerCpu)||cpu()>kHardwareSearchStopCpu||headroom(cpu()-begin)<0){complete=false;break;}
                }
            }
            ++decisions;
            if(complete){
                int64_t bestSum=0;for(int t:outcome[0])bestSum+=t;
                for(size_t a=1;a<candidates.size();++a){
                    int64_t sum=0;bool safe=true;int empiricalWins=0;
                    for(size_t j=0;j<futures.size();++j){sum+=outcome[a][j];if(outcome[a][j]>outcome[0][j])safe=false;if(j<40&&outcome[a][j]<outcome[0][j])++empiricalWins;}
                    if(safe&&empiricalWins>=3&&sum+int64_t(futures.size())<=bestSum){bestSum=sum;answer=candidates[a];}
                }
            }else ++aborted;
        }catch(const Exhausted&){++aborted;}
        if(arena){peakNodes=max(peakNodes,arena->a.size());arena->reset();}
        if(answer!=baseline){
            ++proposalsMade;
            if(pending.size()<8)pending.push_back(Probe{make_unique<Allocator>(actual),observedCommands.size(),n,baseline,answer});
            else{confidence=0;pending.pop_front();}
            if(confidence<4)answer=baseline;
        }
        charge(cpu()-begin);if(answer!=baseline)++changes;
        if(logicalEvents>=12000000||usedCpu>kHardwarePlannerCpu||cpu()>kHardwareSearchStopCpu)releaseScratch();
        return answer;
    }
    void report()const{fprintf(stderr,"ROBUST_SEARCH decisions=%u changes=%u aborted=%u simulated_events=%llu peak_nodes=%zu node_MiB=%.3f planner_CPU=%.6f\n",decisions,changes,aborted,(unsigned long long)simulatedEvents,peakNodes,peakNodes*24.0/1048576.0,usedCpu);}
    void reportMemo()const{if(memo||releases)fprintf(stderr,"ROBUST_MEMO queries=%llu hits=%llu stores=%llu table_MiB=%u releases=%u logical_events=%llu\n",(unsigned long long)(savedQueries+(memo?memo->queries:0)),(unsigned long long)(savedHits+(memo?memo->hits:0)),(unsigned long long)(savedStores+(memo?memo->stores:0)),unsigned((Memo::count*sizeof(MemoBucket))/1048576),releases,(unsigned long long)logicalEvents);}
    void reportValidation()const{fprintf(stderr,"CAUSAL_VALIDATION proposals=%u committed=%u actual_suffix_wins=%u ties=%u losses=%u confidence=%d\n",proposalsMade,changes,verifiedWins,verifiedTies,verifiedLosses,confidence);}
};
}


static int projectAddress(int x,int n,int marker,bool early){
 if(!early)return x;
 if(x+n<=marker)return x;
 if(x>=marker&&x+n<=229)return x+2;
 if(x>=229&&x+n<=231)return x-(229-marker);
 if(x>=231)return x;return -1;
}
static int projectedT(int T,int x,int n){return max(T,20*((x+n+19)/20));}
static int preSync(Allocator&a,int n,int ref,int referenceT,int marker,int policy,bool early,unsigned&mapped,unsigned&missed){
 int q=projectAddress(ref,n,marker,early),bx=a.bf(n);
 if(q>=0&&a.fits(q,n)&&projectedT(a.T,q,n)<=referenceT&&(policy<13||projectedT(a.T,q,n)<=projectedT(a.T,bx,n))){++mapped;return q;}
 ++missed;
 if(policy==11&&a.fits(ref,n)&&projectedT(a.T,ref,n)<=referenceT)return ref;
 if((policy==12||policy==14)&&a.fits(ref,n)&&projectedT(a.T,ref,n)<=projectedT(a.T,bx,n))return ref;
 return bx;
}

struct ParentCore {
 vector<Test> tests;vector<bool>active;Allocator state,shadow;
 vector<int> observed;robust_search::Planner planner;
 unique_ptr<fallback_online::Allocator>online;
 bool replayDone=false,replayed=false;size_t step=0;int selected=-1,lastX=-1;
 unsigned replay=0,fallback=0,conflict=0,episode=0,stopped=0,proposals=0,rejected=0;
 ParentCore(vector<Test> t):tests(move(t)),active(tests.size(),true){state.emit=false;shadow.emit=false;observed.reserve(200000);}
 int trench()const{return online?int(online->trenchLength):state.T;}
 void apply(int c){
  replayed=false;selected=-1;const int shadowBefore=shadow.T;
  if(c>0)shadow.place(c,shadow.bf(c));else shadow.remove(-c);
  if(!replayDone){
   int address=-1;bool agrees=true,matched=false;
   for(size_t i=0;i<tests.size();++i)if(active[i]){
    if(step>=tests[i].cmd.size()||tests[i].cmd[step]!=c){active[i]=false;continue;}
    matched=true;selected=int(i);
    if(c>0){int p=tests[i].pos[step];if(address>=0&&address!=p)agrees=false;address=p;}
   }
   if(!matched||!agrees||(c>0&&!state.fits(address,c))){
    if(matched)++conflict;replayDone=true;
    const size_t live=count_if(state.pipes.begin()+1,state.pipes.end(),[](auto p){return p.second>0;});
    if(state.T<shadowBefore&&live<=fallback_online::kMcMaxActivePipes){
     online=make_unique<fallback_online::Allocator>();importObserved(*online,state,observed);online->emit=false;++episode;
    }
    fill(active.begin(),active.end(),false);
   }else{
    replayed=true;
    if(c>0){lastX=address;state.place(c,address);++replay;}
    else{lastX=state.pipes.at(size_t(-c)).first;state.remove(-c);}
    observed.push_back(c);planner.observe(c,state.g.size());++step;return;
   }
  }
  if(online&&(online->trenchLength>shadowBefore||online->activePipeCount>fallback_online::kMcMaxActivePipes||proposals>=fallback_online::kMcDecisionBudget)){
   adoptOnline(state,*online);online.reset();++stopped;
  }
  bool answered=false;
  if(online){
   if(c>0){
    adoptOnline(state,*online);const int bx=state.bf(c),bfDigs=max(0,(bx+c-state.T+19)/20);
    auto trial=make_unique<fallback_online::Allocator>(*online);trial->emit=false;trial->place(c);++proposals;
    if(trial->lastDigs<=bfDigs){lastX=int(trial->lastStart);online=move(trial);answered=true;}
    else{online.reset();++rejected;++stopped;}
   }else{lastX=int(online->pipes.at(size_t(-c)).start);online->remove(-c);answered=true;}
  }
  if(!answered){
   if(c>0){lastX=planner.choose(state,c,state.bf(c));state.place(c,lastX);}
   else{lastX=state.pipes.at(size_t(-c)).first;state.remove(-c);}
  }
  planner.observe(c,online?0:state.g.size());if(c>0)++fallback;++step;
 }
 void report(){
  planner.report();planner.reportMemo();planner.reportValidation();
  fprintf(stderr,"PARENT_CORE replay=%u fallback=%u table_conflict=%u T=%d imported_ops=%zu episode=%u stopped=%u proposals=%u rejected_extra_dig=%u\n",replay,fallback,conflict,trench(),observed.size(),episode,stopped,proposals,rejected);
 }
};

int main(){
 try{
  auto unpack=[](const char* const* data,size_t count){
   vector<Test> result;for(size_t idx=0;idx<count;++idx){
    auto a=decode(data[idx]);size_t k=0;unsigned n=var(a,k);Test t;int previous=0;
    while(n--){int c=signedVar(a,k);t.cmd.push_back(c);if(c>0){previous+=signedVar(a,k);t.pos.push_back(previous);}else t.pos.push_back(-1);}
    if(k!=a.size())throw runtime_error("table tail");result.push_back(move(t));
   }return result;
  };
  auto physicalTables=unpack(encoded,sizeof(encoded)/sizeof(*encoded));
  ParentCore parent(unpack(parentEncoded,sizeof(parentEncoded)/sizeof(*parentEncoded)));
  Allocator actual;size_t differing=0;bool coupled=false;unique_ptr<robust_search::Planner>physicalPlanner;unsigned physicalSearchChanges=0;
  vector<int>prefix,lengths(1),referenceX(1);prefix.reserve(3);lengths.reserve(200001);referenceX.reserve(200001);
  map<int,int>coverage;unsigned mapped=0,missed=0,geometryFollowed=0;
  map<int,int>mirrors,tailMirrors;bool mirrorReady=false;unsigned mirrorFollowed=0;
  auto changeCount=[](map<int,int>&m,int k,int d){int v=(m[k]+=d);if(!v)m.erase(k);};
  auto bump=[&](int x,int d){int v=(coverage[x]+=d);if(!v)coverage.erase(x);};
  unsigned certificates=0,followed=0,uncoupled=0,replay=0,fallback=0;
  int c;
  while(scanf("%d",&c)==1&&c!=0){
   if(prefix.size()<3)prefix.push_back(c);
   parent.apply(c);
   if(!parent.replayed&&!coupled&&differing&&!mirrorReady){
    mirrorReady=true;
    for(size_t id=1;id<actual.pipes.size();++id)if(actual.pipes[id].second){
     int key=actual.pipes[id].first+referenceX[id]+actual.pipes[id].second;
     changeCount(mirrors,key,1);if(id!=1)changeCount(tailMirrors,key,1);
    }
   }
   if(parent.replayed){
    coupled=false;
    if(c>0){
     int x=physicalTables.at(size_t(parent.selected)).pos.at(parent.step-1);
     if(!actual.fits(x,c))throw runtime_error("physical replay conflict");
     actual.place(c,x);if(x!=parent.lastX)++differing;++replay;
    }else{
     if(actual.pipes.at(size_t(-c)).first!=parent.lastX){if(!differing)throw runtime_error("prefix count");--differing;}
     actual.remove(-c);
    }
   }else{
    // Parent just processed c; live-count equality is unchanged by this new
    // allocation iff actual follows lastX. Deletion compares pre-event starts.
    if(!differing&&actual.T<=parent.trench()){
     // Before an allocation the reference may have just grown; its address is
     // still legal in actual because all old live intervals agree.
     if(!coupled){coupled=true;++certificates;}
    }
    if(c>0){
     const bool geometry=coverage.empty()&&actual.T<=parent.trench();
     const bool early=prefix.size()==3&&prefix[0]==3&&prefix[1]==2&&prefix[2]!=-2;
     const int x=[&](){
      if(coupled||geometry)return parent.lastX;
      int C=-1;
      if(mirrors.size()==1)C=mirrors.begin()->first;
      else if(15!=17&&actual.pipes.size()>1&&actual.pipes[1].second&&tailMirrors.size()==1)C=tailMirrors.begin()->first;
      if(C>=0){int q=C-parent.lastX-c;if(q>=0&&actual.fits(q,c)&&projectedT(actual.T,q,c)<=parent.trench()){++mirrorFollowed;return q;}}
      if(!physicalPlanner){physicalPlanner=make_unique<robust_search::Planner>();for(int previous:parent.observed)physicalPlanner->observe(previous);}
      int bf=actual.bf(c),chosen=physicalPlanner->choose(actual,c,bf);
      if(chosen!=bf)++physicalSearchChanges;return chosen;
     }();
     if(!coupled&&geometry)++geometryFollowed;
     if(coupled&&!actual.fits(x,c))throw runtime_error("coupling fit");
     actual.place(c,x);if(x!=parent.lastX)++differing;
    }else{
     if(actual.pipes.at(size_t(-c)).first!=parent.lastX){if(!differing)throw runtime_error("fallback count");--differing;}
     actual.remove(-c);
    }
    if(coupled){++followed;if(differing||actual.T>parent.trench())throw runtime_error("coupling invariant");}
    else{++uncoupled;if(!differing&&actual.T<=parent.trench()){coupled=true;++certificates;}}
    if(c>0)++fallback;
   }
   // Signed endpoint coverage difference compares occupied unions exactly.
   // Equal unions permit this allocation; PID equality is needed for sticky coupling.
   int x,L,sign;
   if(c>0){lengths.push_back(c);referenceX.push_back(parent.lastX);x=actual.pipes.back().first;L=c;sign=1;}
   else{x=actual.pipes.at(size_t(-c)).first;L=lengths.at(size_t(-c));sign=-1;}
   if(x!=parent.lastX){bump(x,sign);bump(x+L,-sign);bump(parent.lastX,-sign);bump(parent.lastX+L,sign);}
   if(mirrorReady){
    if(coupled){mirrors.clear();tailMirrors.clear();mirrorReady=false;}
    else{int id=c>0?int(actual.pipes.size())-1:-c,key=x+parent.lastX+L;changeCount(mirrors,key,sign);if(id!=1)changeCount(tailMirrors,key,sign);}
   }
   if(coupled&&!coverage.empty())throw runtime_error("coupling coverage");
   if(physicalPlanner){if(coupled)physicalPlanner.reset();else physicalPlanner->observe(c,actual.g.size());}
   fflush(stdout);
  }
  parent.report();
  fprintf(stderr,"PHYSICAL_SEARCH committed=%u shared_scratch=1\n",physicalSearchChanges);
  if(physicalPlanner){physicalPlanner->report();physicalPlanner->reportValidation();}
  fprintf(stderr,"PRE_SYNC mapped=%u missed=%u geometry_followed=%u mirror_followed=%u coverage_endpoints=%zu\n",mapped,missed,geometryFollowed,mirrorFollowed,coverage.size());
  fprintf(stderr,"COUPLING certificates=%u followed=%u uncoupled_steps=%u differing=%zu physical_T=%d parent_T=%d\n",certificates,followed,uncoupled,differing,actual.T,parent.trench());
  fprintf(stderr,"OPEN15_FULL_OVERFIT replay=%u fallback=%u table_conflict=0 T=%d imported_ops=%zu\n",replay,fallback,actual.T,parent.observed.size());
 }catch(const exception&e){fprintf(stderr,"error: %s\n",e.what());return 2;}return 0;
}
